"""Injects model results and evidence tables into the dashboard template -> dashboard/index.html"""
import json, os, re
HERE = os.path.dirname(os.path.abspath(__file__))
res = json.load(open(os.path.join(HERE, "..", "model", "results.json")))
params = json.load(open(os.path.join(HERE, "..", "model", "params.json")))
V = lambda node: node["value"] if isinstance(node, dict) and "value" in node else node
hp = params["routes"]["hybrid_2blocks_2y"]; g = params["general"]
P = {k: V(hp[k]) for k in ("multiple_median","seller_finance_share","vendor_loan_term_years","vendor_loan_rate","manager_cost")}
P.update({k: V(g[k]) for k in ("pg_share_of_facility","senior_debt_max_ebitda_multiple","dscr_min")})

def slim(r):
    keep = ("route","kind","p_target_by_2034","p_500k_by_2034","p_floor_breached","p_business_acquired","p_business_failed","p_sold","mean_employed_days_total","nw_percentiles_2034","median_owner_draw_when_operating","mean_hours_by_year","fan","years","conditional")
    return {k: r[k] for k in keep}
data = {
 "routes_fit": {k: slim(v) for k, v in res["routes_fit"].items()},
 "routes_raw": {k: {"p_target_by_2034": v["p_target_by_2034"], "p_500k_by_2034": v["p_500k_by_2034"]} for k, v in res["routes_raw"].items()},
 "sweep_labour": res["sweep_labour"], "tornado": res["tornado"], "scenarios": res["scenarios"], "horizon": res["horizon"], "params": P,
}
fitrows = [
 ("hybrid_2blocks_2y","selling","low","yes","15 → 20","manager leaves (35%); seller-dependency; one supplier line", "Selling and sourcing seat is the proven mode (age-22 business, Etsy); takeovers survive better than start-ups in years 1–2 (French cohort OR 0.46); detail-orientation 15% raises DD risk."),
 ("buy_distributor","selling","low","yes","35 → 20","exclusive agreement termination (2–3 yr terms, 3–12 months' notice)", "Wholesale payroll only 16% of revenue so a salaried manager is affordable; 0 of 31 listings offer vendor finance; only 2 of 31 say management can absorb the owner's role."),
 ("buy_services","selling","medium","yes","35 → 22","wage floor (NLW +4.1%, employer NIC 15%) on ~50% payroll", "Owner-led cleaning firms earn 21% net but 8.5% once the owner stops doing the work (Plimsoll 2026): the margin is the owner's labour."),
 ("buy_hire","mixed","medium","yes","35 → 22","fleet capex; construction output −2.5–3.3% in 2026", "Asset-backed and bankable; but hire owners in the listings operate the kit and depots are provincial; asks anchor on fleet value (3.4×)."),
 ("buy_logistics","mixed","medium","yes","38 → 25","driver dependence; ~2% haulage margin; lowest 5-yr survival sector", "Retiring owners are commonest here (42%) and manager-in-place is stated most (25%), but margins leave no slack for a non-operator."),
 ("buy_ecommerce","mixed","medium","partly","30 → 20","Amazon-only (5 of 13 EF listings); Etsy take rate 24.2%", "The Etsy playbook fits; 'cannot create demand from nothing' does not. Sold multiples 1.4–2.0× vs asks 2.2–3.6×."),
 ("buy_saas","technical","high","yes","35 → 30","founder-dependent code; churn", "'The buyer is largely purchasing a job' (FE International). Implementer is the lowest archetype; 0/6 solo builds."),
 ("buy_agency","technical","high","yes","40 → 30","key person; unpriced labour (the Rock lesson)", "Most sub-£300k agencies are owner-delivered; only 5 of 17 clearly have teams."),
 ("build_services","mixed","high","partly","45 → 30","owner is the workforce in year 1", "Year one is five-day operator work with no manager: the shape the SOT says health cannot sustain (IBD work impairment 39%, fatigue OR 4.3)."),
 ("build_ecommerce","technical","high","no","40 → 25","platform; 3-yr survival 35.8% (SIC 479)", "Three demand-creation attempts failed; online retail has the second-worst 3-year survival of any 3-digit sector."),
 ("build_aws_partner","selling","high","partly","40 → 35","founder is the delivery capacity", "Contracting under a brand until a team exists; only 3% of UK computer consultancies exceed £1m turnover; Capita ended after five weeks of sustained delivery."),
 ("build_ai_app","technical","high","no","35 → 30","product-market fit (43% of post-mortems)", "0/6 solo builds; SOT's own 20–30% odds; a second person and warm customers help (Howell & Hall 2026) but do not change the base rate."),
 ("hybrid_plan_app","selling","medium","yes","15 → 28","the app is optional and killable", "The version of the app bet the evidence favours: customers already owned, second person implements, capital from the risk pot two years after completion."),
]
data["fit"] = [{"route":r,"seat":s,"impl":i,"demand":d,"hours":h,"risk":k,"fit":V(params["routes"][r]["fit_multiplier"]),"why":w} for r,s,i,d,h,k,w in fitrows]
